import {BUSINESSES,businessType} from './businesses.js';
import {CITY_TILES} from './maps.js';
import {GROUPS} from './content.js';
import {mapPoint,mapEdges,nextMapFocus} from './navigation.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class MiniMap{
 constructor(root,{jump,inspect}){this.tiles=CITY_TILES;this.root=root;this.jump=jump;this.inspect=inspect;this.selected=0;this.followSelection=true;this.lastTurn='';const media=matchMedia('(min-width:1000px) and (min-height:650px)');this.expanded=media.matches;this.touched=false;
  const path=mapEdges(this.tiles).map(e=>`M${e.a.x},${e.a.y}L${e.b.x},${e.b.y}`).join(' ');
  root.innerHTML=`<button class="mini-toggle" aria-expanded="${this.expanded}" aria-controls="miniBody"><span>◈ 全岛地图</span><span class="mini-chevron">${this.expanded?'−':'+'}</span></button><div id="miniBody" ${this.expanded?'':'hidden'}><svg class="mini-svg" role="group" viewBox="0 0 360 250" aria-label="全岛路线，可用方向键选择地块，回车定位"><rect width="360" height="250" rx="14" fill="#b6cd9c"/><rect x="48" y="116" width="264" height="18" rx="8" fill="#81afb2"/><path d="${path}" stroke="#eee0b7" stroke-width="19" fill="none" stroke-linecap="round"/><path d="${path}" stroke="#738b7f" stroke-width="12" fill="none" stroke-linecap="round"/>${this.tiles.map(t=>{const p=mapPoint(t,this.tiles);return`<circle class="mini-node" data-mini-tile="${t.id}" cx="${p.x}" cy="${p.y}" r="${t.kind==='property'?5:7}" fill="${t.kind==='property'?GROUPS[t.group].color:'#fff0b7'}" stroke="#5b735b" stroke-width="1.4" role="button" tabindex="${t.id===0?0:-1}" aria-label="${t.id+1}. ${esc(t.name)}"><title>${esc(t.name)}</title></circle>`;}).join('')}<circle class="mini-selected" r="11" stroke="#fff6cd" stroke-width="2.5" fill="none" stroke-dasharray="4 3" pointer-events="none"/><g class="mini-pawns" pointer-events="none"></g></svg><div class="mini-footer"><span class="mini-name"></span><button class="mini-inspect">详情</button></div><span class="sr-only">方向键选择地块，回车定位，详情查看价格与归属。</span></div>`;
  this.body=root.querySelector('#miniBody');this.toggle=root.querySelector('.mini-toggle');this.nodes=[...root.querySelectorAll('[data-mini-tile]')];this.marker=root.querySelector('.mini-selected');this.name=root.querySelector('.mini-name');this.toggle.addEventListener('click',()=>{this.touched=true;this.setExpanded(!this.expanded);});media.addEventListener('change',e=>{if(!this.touched)this.setExpanded(e.matches);});
  const choose=e=>{const node=e.target.closest('[data-mini-tile]');if(!node)return;this.select(+node.dataset.miniTile,false);this.jump(this.selected);};root.querySelector('svg').addEventListener('click',choose);
  root.querySelector('svg').addEventListener('keydown',e=>{const node=e.target.closest('[data-mini-tile]');if(!node)return;if(['Enter',' '].includes(e.key)){e.preventDefault();choose(e);return;}if(['Home','End','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();this.select(nextMapFocus(+node.dataset.miniTile,e.key),false);this.nodes[this.selected].focus();}});root.querySelector('.mini-inspect').addEventListener('click',()=>this.inspect(this.selected));this.select(0,true);this.setExpanded(this.expanded);
 }
 setMap(tiles){this.tiles=tiles;const path=mapEdges(tiles).map(e=>`M${e.a.x},${e.a.y}L${e.b.x},${e.b.y}`).join(' ');for(const line of this.root.querySelectorAll('.mini-svg>path'))line.setAttribute('d',path);for(const t of tiles){const node=this.nodes[t.id],p=mapPoint(t,tiles);node.setAttribute('cx',p.x);node.setAttribute('cy',p.y);node.setAttribute('r',t.kind==='property'?5:7);node.querySelector('title').textContent=t.name;node.setAttribute('fill',t.kind==='property'?GROUPS[t.group].color:'#fff0b7');node.setAttribute('aria-label',`${t.id+1}. ${t.name}`);}this.lastTurn='';}
 setExpanded(value){this.expanded=value;this.toggle.setAttribute('aria-expanded',String(value));this.toggle.querySelector('.mini-chevron').textContent=value?'−':'+';this.body.hidden=!value;this.root.classList.toggle('is-collapsed',!value);}
 select(id,follow=false){if(!this.tiles[id])return;this.selected=id;this.followSelection=follow;for(const node of this.nodes)node.setAttribute('tabindex',+node.dataset.miniTile===id?'0':'-1');const p=mapPoint(this.tiles[id],this.tiles);this.marker.setAttribute('cx',p.x);this.marker.setAttribute('cy',p.y);this.name.textContent=this.labels?.[id]||`${id+1}. ${this.tiles[id].name}`;}
 sync(game,{visible=true}={}){if(this.tiles!==game.tiles)this.setMap(game.tiles);this.root.hidden=!visible;if(!visible)return;const s=game.s,turn=`${s.round}:${s.current}`;if(turn!==this.lastTurn){this.lastTurn=turn;this.followSelection=true;}this.labels=[];if(this.followSelection)this.select(game.player.pos,true);for(const t of this.tiles){const node=this.nodes[t.id],o=s.ownership[t.id];node.setAttribute('fill',o?game.char(s.players[o.player]).estateColor:t.kind==='property'?GROUPS[t.group].color:'#fff0b7');node.setAttribute('stroke-width',o?'3':'1.4');const label=`${t.id+1}. ${t.name}${o?' · '+game.char(s.players[o.player]).name+' · '+(o.level?BUSINESSES[businessType(o)].name+' '+o.level+'级':'待建空地'):''}`;this.labels[t.id]=label;node.setAttribute('aria-label',label);node.querySelector('title').textContent=label;}
  this.name.textContent=this.labels[this.selected];const pawns=s.players.filter(p=>p.alive).map(p=>{const point=mapPoint(this.tiles[p.pos],this.tiles),color=game.char(p).color;return`<circle cx="${point.x+(p.id-(s.players.length-1)/2)*5}" cy="${point.y-5}" r="${p.id===s.current?6:4.5}" fill="${color}" stroke="${p.id===s.current?'#fffbe2':'#644727'}" stroke-width="${p.id===s.current?3:2}"/>`;}).join('');this.root.querySelector('.mini-pawns').innerHTML=pawns;
 }
}
